import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"AS 路径与策略","description":"","frontmatter":{"title":"AS 路径与策略","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-policy.md","filePath":"cs/bgp-policy.md","lastUpdated":1789023840000}'),A={name:"cs/bgp-policy.md"};function h(_,a,E,P,u,B){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="as-路径与策略" tabindex="-1">AS 路径与策略 <a class="header-anchor" href="#as-路径与策略" aria-label="Permalink to &quot;AS 路径与策略&quot;">​</a></h1><div class="epigraph"><p>BGP 选出的路由先满足商业关系，再看路径属性；AS_PATH 用来防环，不是跳数最小。</p><footer>—— 据 Rekhter, Li and Hares, RFC 4271；Kurose and Ross 对客户–对等–提供者的整理</footer></div><p><a href="/cs/bgp-intuition">上一课</a>已经说：BGP 通告路径与属性，不是域内最短路。本课不重讲「为什么不用全球 Dijkstra」。缺口是决策顺序：本地偏好、AS 路径长度、MED、来源、IGP 到下一跳——以及<strong>进出口政策</strong>如何过滤前缀。本课不把 UDP 端口提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/bgp-intuition">BGP 直觉</a>留下「客户、对等、提供者」。没有政策，会话只是交换前缀。典型 Gao–Rexford 直觉：向客户通告能学到的路由，向对等与提供者只通告自己的客户路由——避免成为免费中转。AS_PATH 里若已出现本 AS 则丢弃，这是路径向量对环的检测。<a href="/cs/count-to-infinity">计数到无穷</a> 那种标量加一在此不适用。</p><p><span class="marginnote">LOCAL_PREF 在 AS 内比路径长度更优先。所以「绕远」可以是故意的。RFC 4271 写决策过程；商业关系是教材归纳，不是协议字段名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入站：按邻居类过滤、设本地偏好。决策：在可用路由里按属性次序挑一条，安装进 Loc-RIB，再按政策向其他邻居通告。出口可能改 NEXT_HOP、剥或加团体属性。同一前缀多条路径时，只有选出的那条（及可能的附加路径扩展）影响转发。</p>',8)),(e(),n(c,null,{default:o(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E7%AB%99%E6%94%BF%E7%AD%96%22%5D%20--%3E%20DEC%5B%22%E5%B1%9E%E6%80%A7%E6%AC%A1%E5%BA%8F%E5%86%B3%E7%AD%96%22%5D%0A%20%20DEC%20--%3E%20LOC%5B%22Loc-RIB%20%2F%20FIB%20%E4%B8%8B%E4%B8%80%E8%B7%B3%22%5D%0A%20%20LOC%20--%3E%20OUT%5B%22%E5%87%BA%E7%AB%99%E6%94%BF%E7%AD%96%E5%86%8D%E9%80%9A%E5%91%8A%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>政策把控制平面从「图上最短」改成「允许的图上可转发」。数据平面仍是 <a href="/cs/lpm">LPM</a>：前缀 → BGP 下一跳 → 经 IGP 可达的接口。端到端分组不携带完整 AS 路径；路径只在控制平面防环与排障。错误政策会造成黑洞或意外中转，这是配置故障，不是 IP 转发公式错。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 RPKI 与全部团体约定写成安全课，不引入路由泄漏的操作清单。传输层如何把分组交给进程，下一课 UDP。</p><p>后课默认：跨域路由是带路径的政策选择。主机上的进程还没有端口，下一课最薄的传输。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AS_PATH 防环；决策先政策后长度。</li><li>进出口过滤实施客户/对等/提供者关系。</li><li>进程到进程从下一课 UDP 开始。</li><li>出处：RFC 4271；Kurose and Ross。</li></ul>',7))])}const S=i(A,[["render",h]]);export{m as __pageData,S as default};
